import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"Providers And Models","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/providers/llm.md","filePath":"integrations/providers/llm.md","lastUpdated":1790952322000}'),d={name:"integrations/providers/llm.md"};function r(n,e,s,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="providers-and-models" tabindex="-1">Providers And Models <a class="header-anchor" href="#providers-and-models" aria-label="Permalink to &quot;Providers And Models&quot;">​</a></h1><p>To use Memoh effectively, you usually configure:</p><ul><li>one or more <strong>providers</strong> that define how Memoh talks to upstream APIs</li><li>one or more <strong>models</strong> under those providers</li><li>optional <strong>speech providers</strong> if you want text-to-speech</li><li>optional <strong>transcription providers</strong> if you want speech-to-text</li></ul><p>Chat and embedding providers/models are managed from the <strong>Models</strong> page in the app. Speech models are managed from <a href="./tts/edge.html">TTS Providers</a>, and transcription models are managed from the Transcription settings page.</p><hr><h2 id="provider-basics" tabindex="-1">Provider Basics <a class="header-anchor" href="#provider-basics" aria-label="Permalink to &quot;Provider Basics&quot;">​</a></h2><p>A <strong>provider</strong> stores connection information for one upstream service, such as:</p><ul><li>the API protocol (<code>client_type</code>)</li><li>the base URL if the protocol needs one</li><li>credentials such as an API key or OAuth token</li></ul><p>Typical examples include OpenAI-compatible endpoints, Anthropic, Google Gemini, OpenAI Codex, and GitHub Copilot.</p><h3 id="creating-a-provider" tabindex="-1">Creating A Provider <a class="header-anchor" href="#creating-a-provider" aria-label="Permalink to &quot;Creating A Provider&quot;">​</a></h3><p>Providers are created from a <strong>template catalog</strong>. Each template carries the right client type, base URL, and a curated model list, so you usually only fill in an API key.</p><ol><li>Open the <strong>Models</strong> page from the settings sidebar.</li><li>Click <strong>Add Provider</strong> and pick a template — the list only shows templates you have not configured yet, and it is searchable (including localized vendor names).</li><li>Fill in the credentials the template asks for.</li><li>Save. The provider and its preset models materialize on save.</li></ol><p>Bundled templates include OpenAI, Anthropic, Google, OpenRouter, DeepSeek, <strong>Zhipu AI (bigmodel.cn)</strong>, Z.AI, Azure OpenAI, Cerebras, Cloudflare, Fireworks, Perplexity, Together, and more. Note that <strong>Zhipu AI</strong> (<code>open.bigmodel.cn</code>, mainland-China accounts) and <strong>Z.AI</strong> (<code>api.z.ai</code>, international accounts) are separate templates with separate API-key namespaces — pick the one matching where your key was issued.</p><p>You can still create a fully custom provider when no template fits.</p><p>Common fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Friendly display name, such as <code>OpenAI</code> or <code>Copilot</code>.</td></tr><tr><td><strong>Client Type</strong></td><td>API protocol used by this provider.</td></tr><tr><td><strong>Base URL</strong></td><td>Root API endpoint, when required by the selected client type.</td></tr><tr><td><strong>API Key</strong></td><td>Token-based authentication, when the client type uses direct credentials.</td></tr></tbody></table><h3 id="client-types" tabindex="-1">Client Types <a class="header-anchor" href="#client-types" aria-label="Permalink to &quot;Client Types&quot;">​</a></h3><p>Memoh currently supports these client types:</p><table tabindex="0"><thead><tr><th>Client Type</th><th>Typical Use</th></tr></thead><tbody><tr><td><code>openai-responses</code></td><td>OpenAI Responses API style providers</td></tr><tr><td><code>openai-completions</code></td><td>OpenAI Chat Completions compatible providers</td></tr><tr><td><code>anthropic-messages</code></td><td>Anthropic Messages API</td></tr><tr><td><code>google-generative-ai</code></td><td>Google Gemini API</td></tr><tr><td><code>openai-codex</code></td><td>OpenAI Codex / ChatGPT-backed coding workflow with OAuth</td></tr><tr><td><code>github-copilot</code></td><td>GitHub Copilot with device OAuth</td></tr><tr><td><code>edge-speech</code></td><td>Speech provider type for Microsoft Edge Read Aloud</td></tr><tr><td><code>openai-speech</code></td><td>OpenAI-compatible text-to-speech providers</td></tr><tr><td><code>openai-transcription</code></td><td>OpenAI-compatible speech-to-text providers</td></tr><tr><td><code>openrouter-speech</code></td><td>OpenRouter speech providers</td></tr><tr><td><code>openrouter-transcription</code></td><td>OpenRouter transcription providers</td></tr><tr><td><code>elevenlabs-speech</code></td><td>ElevenLabs speech providers</td></tr><tr><td><code>elevenlabs-transcription</code></td><td>ElevenLabs transcription providers</td></tr><tr><td><code>deepgram-speech</code></td><td>Deepgram speech providers</td></tr><tr><td><code>deepgram-transcription</code></td><td>Deepgram transcription providers</td></tr><tr><td><code>minimax-speech</code></td><td>MiniMax speech providers</td></tr><tr><td><code>volcengine-speech</code></td><td>Volcengine speech providers</td></tr><tr><td><code>alibabacloud-speech</code></td><td>Alibaba Cloud speech providers</td></tr><tr><td><code>microsoft-speech</code></td><td>Microsoft speech providers</td></tr><tr><td><code>google-transcription</code></td><td>Google transcription providers</td></tr></tbody></table><p>Speech and transcription client types are for audio workflows, not for chat. Configure speech through <a href="./tts/edge.html">TTS Providers</a> and transcription through the Transcription settings page. Exact model and voice availability depends on the configured provider template and upstream account.</p><hr><h2 id="oauth-based-providers" tabindex="-1">OAuth-Based Providers <a class="header-anchor" href="#oauth-based-providers" aria-label="Permalink to &quot;OAuth-Based Providers&quot;">​</a></h2><p>Most provider types use a normal API key. Two notable exceptions are <code>openai-codex</code> and <code>github-copilot</code>. Both authenticate with <strong>device authorization</strong> through the same flow, and neither shows an API key field:</p><ol><li>Create and <strong>save</strong> the provider first — authorization is only available from the saved provider&#39;s details panel.</li><li>In the <strong>Account</strong> section, click <strong>Connect</strong>. Memoh shows a verification URL and a one-time user code with an expiry countdown.</li><li>Click <strong>Copy &amp; Open</strong>, enter the code on the provider&#39;s verification page, and Memoh completes authorization automatically.</li></ol><blockquote><p>Only enter the code on the displayed verification URL — device codes can be used for phishing.</p></blockquote><p>The connected account is shown on the provider afterwards, and <strong>Revoke</strong> disconnects it.</p><h3 id="openai-codex" tabindex="-1">OpenAI Codex <a class="header-anchor" href="#openai-codex" aria-label="Permalink to &quot;OpenAI Codex&quot;">​</a></h3><ul><li>Uses the <code>openai-codex</code> client type; the bundled template points at <code>https://chatgpt.com/backend-api</code></li><li>Signs in with your ChatGPT account</li></ul><p>This is a good fit when you want Codex-style model access for coding-oriented workflows.</p><h3 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h3><ul><li>Uses the <code>github-copilot</code> client type</li><li>Signs in with your GitHub account</li></ul><p>GitHub Copilot is especially useful if you already have access to Copilot-backed chat and embedding models and want to reuse that access from Memoh.</p><div class="warning custom-block"><p class="custom-block-title">Upgrade note</p><p>Copilot credentials used to be stored per user. They are now a single provider-level credential, the same as Codex. After upgrading an existing deployment, re-authorize the Copilot provider once.</p></div><h3 id="managed-model-catalogs" tabindex="-1">Managed Model Catalogs <a class="header-anchor" href="#managed-model-catalogs" aria-label="Permalink to &quot;Managed Model Catalogs&quot;">​</a></h3><p>For both OAuth providers, the model list is a <strong>managed catalog</strong> fetched live from the upstream service (Codex has no static model list at all — it always reflects what your ChatGPT account can use):</p><ul><li>The catalog syncs automatically after device authorization, and you can re-import at any time.</li><li>Models that disappear from the upstream catalog are marked unavailable rather than deleted.</li><li>Re-importing is an upsert: newly discovered capabilities are filled in without overwriting your own model configuration.</li></ul><hr><h2 id="importing-models" tabindex="-1">Importing Models <a class="header-anchor" href="#importing-models" aria-label="Permalink to &quot;Importing Models&quot;">​</a></h2><p>After creating a provider, you can import or add models under it.</p><p>Typical flow:</p><ol><li>Select the provider.</li><li>Click <strong>Import Models</strong> if the provider can expose a model catalog.</li><li>Choose the models you want to save into Memoh.</li></ol><p>You can also add models manually when you already know the upstream model ID.</p><h3 id="enabling-models" tabindex="-1">Enabling Models <a class="header-anchor" href="#enabling-models" aria-label="Permalink to &quot;Enabling Models&quot;">​</a></h3><p>Each model row on the provider detail page has an <strong>enable switch</strong>. Disabled models stay visible there for re-enabling, but they disappear from every model picker (bot settings, chat, embedding, and so on).</p><p>The defaults differ by how the model was created:</p><ul><li>Models you add <strong>manually</strong> start enabled.</li><li>Models created by <strong>bulk import</strong> start <strong>disabled</strong>, so importing a large catalog does not flood every picker — enable the ones you actually want to expose.</li></ul><hr><h2 id="model-types" tabindex="-1">Model Types <a class="header-anchor" href="#model-types" aria-label="Permalink to &quot;Model Types&quot;">​</a></h2><p>Memoh distinguishes four model types:</p><table tabindex="0"><thead><tr><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>chat</code></td><td>Main LLMs for conversation, tool use, reasoning, and image generation</td></tr><tr><td><code>embedding</code></td><td>Vector models for memory and retrieval</td></tr><tr><td><code>speech</code></td><td>Text-to-speech models used by TTS providers</td></tr><tr><td><code>transcription</code></td><td>Speech-to-text models used by transcription providers</td></tr></tbody></table><p>Important distinction:</p><ul><li>The <strong>Models</strong> page is primarily where you manage <code>chat</code> and <code>embedding</code> models.</li><li><code>speech</code> models are exposed through <a href="./tts/edge.html">TTS Providers</a>.</li><li><code>transcription</code> models are exposed through the Transcription settings page.</li></ul><hr><h2 id="chat-model-configuration" tabindex="-1">Chat Model Configuration <a class="header-anchor" href="#chat-model-configuration" aria-label="Permalink to &quot;Chat Model Configuration&quot;">​</a></h2><p>When adding a chat model, the most important fields are:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Model ID</strong></td><td>Exact upstream identifier, such as <code>gpt-4o</code> or <code>claude-sonnet-4.6</code>.</td></tr><tr><td><strong>Name</strong></td><td>Friendly display name shown in the UI.</td></tr><tr><td><strong>Description</strong></td><td>Optional free text shown as a tooltip in model lists and searchable in model pickers.</td></tr><tr><td><strong>Compatibilities</strong></td><td>Feature flags such as <code>vision</code>, <code>tool-call</code>, <code>image-output</code>, and <code>reasoning</code>.</td></tr><tr><td><strong>Context Window</strong></td><td>Approximate maximum context budget for the model.</td></tr></tbody></table><h3 id="compatibilities" tabindex="-1">Compatibilities <a class="header-anchor" href="#compatibilities" aria-label="Permalink to &quot;Compatibilities&quot;">​</a></h3><p>Memoh uses compatibility flags to decide which features a model can safely power:</p><table tabindex="0"><thead><tr><th>Compatibility</th><th>Meaning</th></tr></thead><tbody><tr><td><code>vision</code></td><td>Model can accept images as input</td></tr><tr><td><code>tool-call</code></td><td>Model can call tools</td></tr><tr><td><code>image-output</code></td><td>Model can generate images</td></tr><tr><td><code>reasoning</code></td><td>Model exposes explicit reasoning modes / effort levels</td></tr></tbody></table><p>If a model supports reasoning, it may also declare <code>reasoning_efforts</code> such as <code>none</code>, <code>low</code>, <code>medium</code>, <code>high</code>, or <code>xhigh</code>.</p><h3 id="context-window" tabindex="-1"><code>context_window</code> <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;`context_window`&quot;">​</a></h3><p><code>context_window</code> is important because Memoh uses it to:</p><ul><li>calculate session context usage in the app</li><li>power <code>/status</code> output</li><li>decide when a session is approaching its prompt limit</li><li>guide <a href="./../../guides/compaction.html">Context Compaction</a></li></ul><p>If you leave <code>context_window</code> empty, the model can still be used, but Memoh cannot show an exact usage percentage for that model.</p><h3 id="image-generation-models" tabindex="-1">Image Generation Models <a class="header-anchor" href="#image-generation-models" aria-label="Permalink to &quot;Image Generation Models&quot;">​</a></h3><p>Memoh now lets you assign an <strong>Image Generation Model</strong> to a bot. This model must be a chat model whose compatibilities include <code>image-output</code>.</p><p>That keeps image generation separate from your default chat model when needed.</p><hr><h2 id="embedding-models" tabindex="-1">Embedding Models <a class="header-anchor" href="#embedding-models" aria-label="Permalink to &quot;Embedding Models&quot;">​</a></h2><p>Embedding models are used for semantic indexing and retrieval.</p><p>The required field is:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Dimensions</strong></td><td>Vector size for the embedding output, such as <code>1536</code>.</td></tr></tbody></table><p>Use embedding models with memory providers or any feature that relies on vector search.</p><hr><h2 id="speech-and-transcription-models" tabindex="-1">Speech And Transcription Models <a class="header-anchor" href="#speech-and-transcription-models" aria-label="Permalink to &quot;Speech And Transcription Models&quot;">​</a></h2><p>Speech models are managed from <a href="./tts/edge.html">TTS Providers</a>, not from the standard chat provider flow.</p><p>Current speech provider categories include:</p><ul><li>Edge via <code>edge-speech</code></li><li>OpenAI-compatible via <code>openai-speech</code></li><li>OpenRouter via <code>openrouter-speech</code></li><li>ElevenLabs via <code>elevenlabs-speech</code></li><li>Deepgram via <code>deepgram-speech</code></li><li>MiniMax via <code>minimax-speech</code></li><li>Volcengine via <code>volcengine-speech</code></li><li>Alibaba Cloud via <code>alibabacloud-speech</code></li><li>Microsoft via <code>microsoft-speech</code></li></ul><p>Transcription models are managed from the Transcription settings page. Current transcription provider categories include:</p><ul><li>OpenAI-compatible via <code>openai-transcription</code></li><li>OpenRouter via <code>openrouter-transcription</code></li><li>ElevenLabs via <code>elevenlabs-transcription</code></li><li>Deepgram via <code>deepgram-transcription</code></li><li>Google via <code>google-transcription</code></li></ul><p>This separation matters because audio models have provider-specific voice, format, speed, pitch, language, and recognition settings that do not apply to chat or embedding models.</p><hr><h2 id="recommended-mental-model" tabindex="-1">Recommended Mental Model <a class="header-anchor" href="#recommended-mental-model" aria-label="Permalink to &quot;Recommended Mental Model&quot;">​</a></h2><p>For most bots, think in terms of parallel model roles:</p><ul><li><strong>Chat model</strong> for normal conversations</li><li><strong>Embedding model</strong> for memory search</li><li><strong>Speech / transcription / image models</strong> for side capabilities such as TTS, speech-to-text, and image generation</li></ul><p>You do not need to force one model to do everything.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>To assign chat, image, memory, and TTS settings to a bot, see <a href="./../../guides/working-with-bots.html">Bot Management</a>.</li><li>To configure speech providers and speech models, see <a href="./tts/edge.html">TTS Providers</a>.</li><li>To configure speech-to-text, open the Transcription settings page in the app.</li></ul>',89)])])}const g=t(d,[["render",r]]);export{m as __pageData,g as default};
